import UIKit
final class PoliciesViewController:UIViewController,PoliciesView{var presenter:PoliciesPresenting!;private var items:[Policy] = [];private let table = UITableView(frame:.zero,style:.insetGrouped);private let stateView = StateView();override func viewDidLoad(){super.viewDidLoad();title = "My Policies";view.backgroundColor = .systemGroupedBackground;table.dataSource = self;view.addSubview(table);table.pinToEdges(of:view);view.addSubview(stateView);stateView.pinToEdges(of:view);stateView.backgroundColor = .systemGroupedBackground;presenter.viewDidLoad()};func show(_ items:[Policy]){self.items = items;table.reloadData()};func showLoading(_ visible:Bool){visible ? stateView.showLoading() : stateView.hide()}}
extension PoliciesViewController:UITableViewDataSource{func tableView(_ tableView:UITableView,numberOfRowsInSection section:Int)->Int{items.count};func tableView(_ tableView:UITableView,cellForRowAt indexPath:IndexPath)->UITableViewCell{let p = items[indexPath.row];let c = UITableViewCell(style:.subtitle,reuseIdentifier:nil);var cfg = c.defaultContentConfiguration();cfg.text = p.name;cfg.secondaryText = "Policy \(p.number) • \(p.status)";cfg.image = UIImage(systemName:"shield.checkered");c.contentConfiguration = cfg;c.accessoryType = .disclosureIndicator;return c}}
